  const vehicleSource = normaliseSource(row.vehicle_source);
  const branchGroup = normaliseBranchGroup(row.branch_name);

  if (!agreementType || !inDate) continue;

  const weekEnding = getWeekBucketFriday(inDate);
  if (!weekEnding) continue;

  const isRental = isRentalType(agreementType);
  const isR2B = isR2BType(agreementType);

  for (const fleetKey of Object.keys(FLEET_FILTERS)) {
    if (!sourceMatchesFleet(vehicleSource, fleetKey)) continue;

    const counts = countsByFleet[fleetKey];

    if (isRental) {
      increment(counts.rentals_in, weekEnding);

      if (branchGroup === 'hammersmith') increment(counts.rentals_in_hammersmith, weekEnding);
      if (branchGroup === 'redbridge') increment(counts.rentals_in_redbridge, weekEnding);
      if (branchGroup === 'dulwich') increment(counts.rentals_in_dulwich, weekEnding);
      if (branchGroup === 'hendon_colindale') increment(counts.rentals_in_hendon_colindale, weekEnding);
    }

    if (isR2B) {
      increment(counts.r2b_returns, weekEnding);

      if (branchGroup === 'cardiff') increment(counts.r2b_returns_cardiff, weekEnding);
      if (branchGroup === 'manchester') increment(counts.r2b_returns_manchester, weekEnding);
      if (branchGroup === 'shah_manchester') increment(counts.r2b_returns_shah_manchester, weekEnding);
      if (branchGroup === 'birmingham') increment(counts.r2b_returns_birmingham, weekEnding);
    }
  }
}

const sharedWeeks = getLastNFridays(WEEKS_TO_RETURN);
const output = [];

for (const [fleetKey, counts] of Object.entries(countsByFleet)) {
  for (const week of sharedWeeks) {
    output.push({
      json: {
        _fleet: fleetKey,
        Date: week,

        rentals_in: counts.rentals_in[week] || 0,

        rentals_in_hammersmith: counts.rentals_in_hammersmith[week] || 0,
        rentals_in_redbridge: counts.rentals_in_redbridge[week] || 0,
        rentals_in_dulwich: counts.rentals_in_dulwich[week] || 0,
        rentals_in_hendon_colindale: counts.rentals_in_hendon_colindale[week] || 0,

        r2b_returns: counts.r2b_returns[week] || 0,
        r2b_returns_cardiff: counts.r2b_returns_cardiff[week] || 0,
        r2b_returns_manchester: counts.r2b_returns_manchester[week] || 0,
        r2b_returns_shah_manchester: counts.r2b_returns_shah_manchester[week] || 0,
        r2b_returns_birmingham: counts.r2b_returns_birmingham[week] || 0
      }
    });
  }
}

return output;

const FLEET_FILTERS = {
  all: null,
  otto: ['OTTOCAR', 'LEUMI'],
  weflex: ['LCM', 'TFS', 'TRIPLE-POINT'],
  lcm: ['LCM'],
  tfs: ['TFS'],
  'triple-point': ['TRIPLE-POINT']
};

const RESERVATION_FEE = 99.00;
const DOWNPAYMENT_FIELD = 'downpayment_amount';
const DEPOSIT_FIELD = 'deposit';
const WEEKS_TO_RETURN = 1;

const BRANCH_GROUPS = {
  hammersmith: new Set(['SHEPHERDS BUSH - GOLDHAWK RD']),
  redbridge: new Set(['ILFORD', 'ILFORD - CLEMENTS ROAD CAR PARK']),
  dulwich: new Set(['DULWICH']),
  hendon_colindale: new Set([
    'COLINDALE',
    'COLINDALE - OTTO',
    'COLINDALE / A2Z',
    'HENDON'
  ]),
  cardiff: new Set(['CARDIFF']),
  manchester: new Set(['MANCHESTER - OTTO', 'OTTO CAR - MANCHESTER']),
  shah_manchester: new Set(['MANCHESTER']),
  birmingham: new Set(['BIRMINGHAM', 'OTHER - BIRMINGHAM'])
};

function money(value) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return value;

  const cleaned = String(value)
    .replace(/£/g, '')
    .replace(/,/g, '')
    .trim();

  return Number(cleaned) || 0;
}

function normaliseType(value) {
  return String(value || '')
    .trim()
    .toUpperCase()
    .replace(/_/g, '-')
    .replace(/\s+/g, '-');
}

function normaliseSource(value) {
  return String(value || '')
    .trim()
    .toUpperCase()
    .replace(/_/g, '-')
    .replace(/\s+/g, '-');
}

function normaliseBranchName(value) {
  return String(value || '')
    .trim()
    .toUpperCase()
    .replace(/\s+/g, ' ');
}

function normaliseStatus(value) {
  return String(value || '')
    .trim()
    .toUpperCase();
}

function getMostRecentFridayDate() {
  const today = new Date();
  const utcToday = new Date(Date.UTC(
    today.getUTCFullYear(),
    today.getUTCMonth(),
    today.getUTCDate()
  ));

  const day = utcToday.getUTCDay();
  const daysSinceFriday = (day + 2) % 7;

  utcToday.setUTCDate(utcToday.getUTCDate() - daysSinceFriday);
  utcToday.setUTCHours(0, 0, 0, 0);

  return utcToday;
}

function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

function getLastNFridays(count) {
  const mostRecentFriday = getMostRecentFridayDate();
  const weeks = [];

  for (let i = count - 1; i >= 0; i--) {
    const friday = new Date(mostRecentFriday);
    friday.setUTCDate(mostRecentFriday.getUTCDate() - (i * 7));
    weeks.push(formatDate(friday));
  }

  return weeks;
}

function getWeekBucketFriday(dateValue) {
  if (!dateValue) return null;

  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return null;

  const utcDate = new Date(Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate()
  ));

  const day = utcDate.getUTCDay();
  const daysSinceMonday = (day + 6) % 7;

  const monday = new Date(utcDate);
  monday.setUTCDate(utcDate.getUTCDate() - daysSinceMonday);

  const friday = new Date(monday);
  friday.setUTCDate(monday.getUTCDate() + 4);

  return formatDate(friday);
}

function normaliseBranchGroup(branchName) {
  const normalised = normaliseBranchName(branchName);

  for (const [group, names] of Object.entries(BRANCH_GROUPS)) {
    if (names.has(normalised)) return group;
  }

  return null;
}

function isCompletedReservation(row) {
  return normaliseStatus(row.downpayment_status) === 'SUCCEEDED';
}

function isReservationFee(row) {
  const downpayment = money(row[DOWNPAYMENT_FIELD]);
  return Math.abs(downpayment - RESERVATION_FEE) < 0.001;
}

function isCompletedWebSale(row) {
  const finalDownpayment = money(row.total_due);
  const deposit = money(row[DEPOSIT_FIELD]);

  return finalDownpayment > (0.5 * deposit);
}

function isR2BType(type) {
  return (
    type.includes('R2B') ||
    type.includes('RENT-TO-BUY') ||
    type.includes('RENT TO BUY')
  );
}

function isInServiceRentalType(type) {
  return type.includes('IN-SERVICE-RENTAL');
}

function isRentalType(type) {
  return type.includes('RENTAL') && !isInServiceRentalType(type);
}

function sourceMatchesFleet(vehicleSource, fleetKey) {
  const allowedSources = FLEET_FILTERS[fleetKey];

  if (!allowedSources) return true;

  return allowedSources.includes(vehicleSource);
}

function increment(bucket, week) {
  bucket[week] = (bucket[week] || 0) + 1;
}

function createWeekCounts() {
  return {
    website_reservations: {},
    website_sales: {},

    new_r2b_orders: {},
    used_r2b_orders: {},
    rentals_out: {},
    in_service_rentals_out: {},

    rentals_out_hyundai: {},
    rentals_out_kia: {},
    rentals_out_mercedes: {},
    rentals_out_mg: {},
    rentals_out_nissan: {},
    rentals_out_skoda: {},
    rentals_out_tesla: {},
    rentals_out_toyota: {},
    rentals_out_vw: {},
    rentals_out_polestar: {},

    rentals_out_hammersmith: {},
    new_r2b_hammersmith: {},
    used_r2b_hammersmith: {},

    rentals_out_redbridge: {},
    new_r2b_redbridge: {},
    used_r2b_redbridge: {},

    rentals_out_dulwich: {},
    new_r2b_dulwich: {},
    used_r2b_dulwich: {},

    rentals_out_hendon_colindale: {},
    new_r2b_hendon_colindale: {},
    used_r2b_hendon_colindale: {},

    rentals_out_cardiff: {},
    new_r2b_cardiff: {},
    used_r2b_cardiff: {},

    rentals_out_manchester: {},
    new_r2b_manchester: {},
    used_r2b_manchester: {},

    rentals_out_shah_manchester: {},
    new_r2b_shah_manchester: {},
    used_r2b_shah_manchester: {},

    rentals_out_birmingham: {},
    new_r2b_birmingham: {},
    used_r2b_birmingham: {}
  };
}

const countsByFleet = Object.fromEntries(
  Object.keys(FLEET_FILTERS).map(fleetKey => [fleetKey, createWeekCounts()])
);

for (const item of items) {
  const row = item.json;

  if (!isCompletedReservation(row)) continue;
  if (!isReservationFee(row)) continue;

  const vehicleSource = normaliseSource(row.vehicle_source);
  const applicationType = normaliseType(row.application_type);
  const reservationCreatedDate = row.reservation_created_date;
  const finalDownpaymentCreatedDate = row.final_downpayment_created_date;
  const branchGroup = normaliseBranchGroup(row.branch_name);
  const manufacturerRaw = row.manufacturer;
  const agreementCount = Number(row.agreement_count);

  if (!applicationType) continue;

  const reservationWeekEnding = getWeekBucketFriday(reservationCreatedDate);
  const saleWeekEnding = getWeekBucketFriday(finalDownpaymentCreatedDate);

  const manufacturer = manufacturerRaw
    ? String(manufacturerRaw).trim().toUpperCase()
    : null;

  const isNew = agreementCount <= 1;
  const isUsed = agreementCount > 1;

  const isR2B = isR2BType(applicationType);
  const isRental = isRentalType(applicationType);
  const isInServiceRental = isInServiceRentalType(applicationType);
  const completedWebSale = saleWeekEnding && isCompletedWebSale(row);

  for (const fleetKey of Object.keys(FLEET_FILTERS)) {
    if (!sourceMatchesFleet(vehicleSource, fleetKey)) continue;

    const counts = countsByFleet[fleetKey];

    if (reservationWeekEnding) {
      increment(counts.website_reservations, reservationWeekEnding);
    }

    if (!completedWebSale) continue;

    increment(counts.website_sales, saleWeekEnding);

    if (isR2B && isNew) increment(counts.new_r2b_orders, saleWeekEnding);
    if (isR2B && isUsed) increment(counts.used_r2b_orders, saleWeekEnding);
    if (isRental) increment(counts.rentals_out, saleWeekEnding);
    if (isInServiceRental) increment(counts.in_service_rentals_out, saleWeekEnding);

    if (isRental && manufacturer) {
      if (manufacturer === 'HYUNDAI') increment(counts.rentals_out_hyundai, saleWeekEnding);
      if (manufacturer === 'KIA') increment(counts.rentals_out_kia, saleWeekEnding);
      if (manufacturer === 'MERCEDES' || manufacturer === 'MERCEDES-BENZ') increment(counts.rentals_out_mercedes, saleWeekEnding);
      if (manufacturer === 'MG') increment(counts.rentals_out_mg, saleWeekEnding);
      if (manufacturer === 'NISSAN') increment(counts.rentals_out_nissan, saleWeekEnding);
      if (manufacturer === 'SKODA') increment(counts.rentals_out_skoda, saleWeekEnding);
      if (manufacturer === 'TESLA') increment(counts.rentals_out_tesla, saleWeekEnding);
      if (manufacturer === 'TOYOTA') increment(counts.rentals_out_toyota, saleWeekEnding);
      if (manufacturer === 'VW' || manufacturer === 'VOLKSWAGEN') increment(counts.rentals_out_vw, saleWeekEnding);
      if (manufacturer === 'POLESTAR') increment(counts.rentals_out_polestar, saleWeekEnding);
    }

    if (branchGroup) {
      if (isRental) increment(counts[`rentals_out_${branchGroup}`], saleWeekEnding);
      if (isR2B && isNew) increment(counts[`new_r2b_${branchGroup}`], saleWeekEnding);
      if (isR2B && isUsed) increment(counts[`used_r2b_${branchGroup}`], saleWeekEnding);
    }
  }
}

const sharedWeeks = getLastNFridays(WEEKS_TO_RETURN);
const output = [];

for (const [fleetKey, counts] of Object.entries(countsByFleet)) {
  for (const week of sharedWeeks) {
    output.push({
      json: {
        _fleet: fleetKey,
        Date: week,

        rentals_in: null,
        net_rentals: null,
        net_r2b: null,
        available_vehicles: null,
        available_vehicles_kings_mall: null,
        avg_days_off_road: null,

        r2b_returns_cardiff: null,
        r2b_returns_manchester: null,
        r2b_returns_shah_manchester: null,
        r2b_returns_birmingham: null,

        ...Object.fromEntries(
          Object.entries(counts).map(([key, values]) => [key, values[week] || 0])
        )
      }
    });
  }
}

return output;

const allItems = items;

const KEY_FIELDS = new Set(['_fleet', 'Date']);

const NON_ADDITIVE_FIELDS = new Set([
  'rentals_in',
  'net_rentals',
  'net_r2b',
  'available_vehicles',
  'available_vehicles_kings_mall',
  'avg_days_off_road',
  'r2b_returns',
  'r2b_returns_cardiff',
  'r2b_returns_manchester',
  'r2b_returns_shah_manchester',
  'r2b_returns_birmingham'
]);

function isNumberLike(value) {
  if (value === null || value === undefined || value === '') return false;
  return !Number.isNaN(Number(value));
}

function mergeValue(existingValue, incomingValue, key) {
  if (KEY_FIELDS.has(key)) return incomingValue;

  if (incomingValue === undefined) return existingValue;
  if (existingValue === undefined) return incomingValue;

  if (incomingValue === null || incomingValue === '') return existingValue;
  if (existingValue === null || existingValue === '') return incomingValue;

  if (NON_ADDITIVE_FIELDS.has(key)) {
    return existingValue ?? incomingValue;
  }

  if (isNumberLike(existingValue) && isNumberLike(incomingValue)) {
    return Number(existingValue) + Number(incomingValue);
  }

  return incomingValue;
}

const mergedByFleetAndDate = new Map();

for (const item of allItems) {
  const row = item.json || {};
  const fleet = row._fleet;
  const date = row.Date;

  if (!fleet || !date) continue;

  const mergeKey = `${fleet}__${date}`;

  if (!mergedByFleetAndDate.has(mergeKey)) {
    mergedByFleetAndDate.set(mergeKey, {
      _fleet: fleet,
      Date: date
    });
  }

  const mergedRow = mergedByFleetAndDate.get(mergeKey);

  for (const [key, value] of Object.entries(row)) {
    mergedRow[key] = mergeValue(mergedRow[key], value, key);
  }
}

const fleetOrder = {
  all: 0,
  otto: 1,
  weflex: 2,
  lcm: 3,
  tfs: 4,
  'triple-point': 5
};

return Array.from(mergedByFleetAndDate.values())
  .sort((a, b) => {
    if (a.Date !== b.Date) return String(a.Date).localeCompare(String(b.Date));
    return (fleetOrder[a._fleet] ?? 99) - (fleetOrder[b._fleet] ?? 99);
  })
  .map(json => ({ json }));
